#!/bin/sh
# Regenerate src/light/proto.rs from the pinned lightwalletd-dd protos in this directory (see PIN).
# Needs protoc on PATH (or PROTOC). The generated file is checked in, so building the agent needs no protoc.
set -eu
here=$(cd "$(dirname "$0")" && pwd)
out=$(mktemp -d)
trap 'rm -rf "$out"' EXIT
cargo run --quiet --manifest-path "$here/gen/Cargo.toml" --target-dir "$out/target" -- "$here" "$out"
{
    echo '// @generated by proto/regen.sh from the protos pinned in proto/PIN; do not edit.'
    cat "$out/cash.z.wallet.sdk.rpc.rs"
} > "$here/../src/light/proto.rs"
echo "wrote src/light/proto.rs"
